    "原版大型纹理等比缩小至最长边 512 像素，控制单文件体积；网格顶点不简化。",
    "纹理来自生成器显式 BodypartTexture2DPath；网格别名必须唯一或几何完全相同，否则明确缺失。",
    "肤色与发色取原版调色板第一个颜色，按原始皮肤遮罩红通道进行乘色近似；不影响遮罩外的服装原色，不声称复现完整 Unity 着色器。"
